import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 依赖批次数据访问：批次、成员（窗口快照）、依赖边、阻断明细。
 * 拓扑查询一律按申请编号稳定排序。
 */
@Repository
public class BatchRepository {

    private final JdbcTemplate jdbc;

    public BatchRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    // ---------------- 批次主表 ----------------

    public void insertBatch(CutoverBatchPO po) {
        jdbc.update("""
                INSERT INTO cutover_batch
                  (batch_id, request_uid, fingerprint, status, version, published_at,
                   result_snapshot, created_at, updated_at)
                VALUES (?,?,?,?,?,?,?,?,?)
                """,
                po.getBatchId(), po.getRequestUid(), po.getFingerprint(), po.getStatus(),
                po.getVersion(), Timestamp.valueOf(po.getPublishedAt()),
                po.getResultSnapshot(),
                Timestamp.valueOf(po.getCreatedAt()), Timestamp.valueOf(po.getUpdatedAt()));
    }

    public CutoverBatchPO findBatch(String batchId) {
        List<CutoverBatchPO> list = jdbc.query(
                "SELECT * FROM cutover_batch WHERE batch_id = ?",
                BATCH_MAPPER, batchId);
        return list.isEmpty() ? null : list.get(0);
    }

    public CutoverBatchPO findBatchByRequestUid(String requestUid) {
        List<CutoverBatchPO> list = jdbc.query(
                "SELECT * FROM cutover_batch WHERE request_uid = ?",
                BATCH_MAPPER, requestUid);
        return list.isEmpty() ? null : list.get(0);
    }

    /** 事务内行锁，不存在返回 null。 */
    public CutoverBatchPO lockBatch(String batchId) {
        List<CutoverBatchPO> list = jdbc.query(
                "SELECT * FROM cutover_batch WHERE batch_id = ? FOR UPDATE",
                BATCH_MAPPER, batchId);
        return list.isEmpty() ? null : list.get(0);
    }

    public void updateBatchStatus(String batchId, String status, LocalDateTime updatedAt) {
        jdbc.update("UPDATE cutover_batch SET status = ?, updated_at = ? WHERE batch_id = ?",
                status, Timestamp.valueOf(updatedAt), batchId);
    }

    // ---------------- 成员 ----------------

    public void insertMember(CutoverBatchMemberPO po) {
        jdbc.update("""
                INSERT INTO cutover_batch_member
                  (batch_id, request_id, window_start, window_end, created_at)
                VALUES (?,?,?,?,?)
                """,
                po.getBatchId(), po.getRequestId(),
                Timestamp.valueOf(po.getWindowStart()), Timestamp.valueOf(po.getWindowEnd()),
                Timestamp.valueOf(po.getCreatedAt()));
    }

    /** 成员按申请编号稳定排序。 */
    public List<CutoverBatchMemberPO> listMembers(String batchId) {
        return jdbc.query(
                "SELECT * FROM cutover_batch_member WHERE batch_id = ? ORDER BY request_id",
                MEMBER_MAPPER, batchId);
    }

    public CutoverBatchMemberPO findMemberByRequest(String requestId) {
        List<CutoverBatchMemberPO> list = jdbc.query(
                "SELECT * FROM cutover_batch_member WHERE request_id = ?",
                MEMBER_MAPPER, requestId);
        return list.isEmpty() ? null : list.get(0);
    }

    // ---------------- 依赖边 ----------------

    public void insertEdge(CutoverBatchEdgePO po) {
        jdbc.update("""
                INSERT INTO cutover_batch_edge
                  (batch_id, predecessor, successor, created_at)
                VALUES (?,?,?,?)
                """,
                po.getBatchId(), po.getPredecessor(), po.getSuccessor(),
                Timestamp.valueOf(po.getCreatedAt()));
    }

    /** 边按 (predecessor, successor) 稳定排序。 */
    public List<CutoverBatchEdgePO> listEdges(String batchId) {
        return jdbc.query(
                "SELECT * FROM cutover_batch_edge WHERE batch_id = ?"
                        + " ORDER BY predecessor, successor",
                EDGE_MAPPER, batchId);
    }

    // ---------------- 阻断明细 ----------------

    public void insertBlockDetail(CutoverBlockDetailPO po) {
        jdbc.update("""
                INSERT INTO cutover_block_detail
                  (batch_id, request_id, source_id, blocked_at, created_at)
                VALUES (?,?,?,?,?)
                """,
                po.getBatchId(), po.getRequestId(), po.getSourceId(),
                Timestamp.valueOf(po.getBlockedAt()), Timestamp.valueOf(po.getCreatedAt()));
    }

    /** 阻断明细按 (request_id, source_id) 稳定排序。 */
    public List<CutoverBlockDetailPO> listBlockDetails(String batchId) {
        return jdbc.query(
                "SELECT * FROM cutover_block_detail WHERE batch_id = ?"
                        + " ORDER BY request_id, source_id",
                BLOCK_MAPPER, batchId);
    }

    /** 指定申请的首个阻断来源集合（按来源申请编号排序）。 */
    public List<String> listBlockSources(String batchId, String requestId) {
        return jdbc.queryForList(
                "SELECT source_id FROM cutover_block_detail"
                        + " WHERE batch_id = ? AND request_id = ? ORDER BY source_id",
                String.class, batchId, requestId);
    }

    // ---------------- RowMapper ----------------

    private static final RowMapper<CutoverBatchPO> BATCH_MAPPER = (rs, n) -> {
        CutoverBatchPO po = new CutoverBatchPO();
        po.setId(rs.getLong("id"));
        po.setBatchId(rs.getString("batch_id"));
        po.setRequestUid(rs.getString("request_uid"));
        po.setFingerprint(rs.getString("fingerprint"));
        po.setStatus(rs.getString("status"));
        po.setVersion(rs.getLong("version"));
        po.setPublishedAt(toLdt(rs, "published_at"));
        po.setResultSnapshot(rs.getString("result_snapshot"));
        po.setCreatedAt(toLdt(rs, "created_at"));
        po.setUpdatedAt(toLdt(rs, "updated_at"));
        return po;
    };

    private static final RowMapper<CutoverBatchMemberPO> MEMBER_MAPPER = (rs, n) -> {
        CutoverBatchMemberPO po = new CutoverBatchMemberPO();
        po.setId(rs.getLong("id"));
        po.setBatchId(rs.getString("batch_id"));
        po.setRequestId(rs.getString("request_id"));
        po.setWindowStart(toLdt(rs, "window_start"));
        po.setWindowEnd(toLdt(rs, "window_end"));
        po.setCreatedAt(toLdt(rs, "created_at"));
        return po;
    };

    private static final RowMapper<CutoverBatchEdgePO> EDGE_MAPPER = (rs, n) -> {
        CutoverBatchEdgePO po = new CutoverBatchEdgePO();
        po.setId(rs.getLong("id"));
        po.setBatchId(rs.getString("batch_id"));
        po.setPredecessor(rs.getString("predecessor"));
        po.setSuccessor(rs.getString("successor"));
        po.setCreatedAt(toLdt(rs, "created_at"));
        return po;
    };

    private static final RowMapper<CutoverBlockDetailPO> BLOCK_MAPPER = (rs, n) -> {
        CutoverBlockDetailPO po = new CutoverBlockDetailPO();
        po.setId(rs.getLong("id"));
        po.setBatchId(rs.getString("batch_id"));
        po.setRequestId(rs.getString("request_id"));
