    /** Kahn 拓扑判定：存在环路则整批拒绝。 */
    private void assertAcyclic(Set<String> memberIds, List<BatchEdgeInput> edges) {
        Map<String, Integer> indegree = new HashMap<>();
        Map<String, List<String>> adjacency = new HashMap<>();
        for (String id : memberIds) {
            indegree.put(id, 0);
        }
        for (BatchEdgeInput e : edges) {
            indegree.merge(e.successor(), 1, Integer::sum);
            adjacency.computeIfAbsent(e.predecessor(), k -> new ArrayList<>())
                    .add(e.successor());
        }
        Deque<String> queue = new ArrayDeque<>();
        for (Map.Entry<String, Integer> en : indegree.entrySet()) {
            if (en.getValue() == 0) {
                queue.add(en.getKey());
            }
        }
        int visited = 0;
        while (!queue.isEmpty()) {
            String node = queue.poll();
            visited++;
            for (String next : adjacency.getOrDefault(node, List.of())) {
                if (indegree.merge(next, -1, Integer::sum) == 0) {
                    queue.add(next);
                }
            }
        }
        if (visited != memberIds.size()) {
            throw new BusinessRuleException("依赖边存在环路，整批拒绝");
        }
    }

    private BatchView buildView(String batchId, String status, Long version,
                                LocalDateTime publishedAt,
                                List<CutoverBatchMemberPO> members,
                                List<CutoverBatchEdgePO> edges,
                                List<String> memberStatuses,
                                Map<String, List<String>> blockSources) {
        List<BatchMemberView> memberViews = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) {
            CutoverBatchMemberPO m = members.get(i);
            memberViews.add(new BatchMemberView(m.getRequestId(),
                    i < memberStatuses.size() ? memberStatuses.get(i) : null,
                    m.getWindowStart(), m.getWindowEnd(),
                    blockSources.getOrDefault(m.getRequestId(), List.of())));
        }
        List<BatchEdgeView> edgeViews = edges.stream()
                .map(e -> new BatchEdgeView(e.getPredecessor(), e.getSuccessor()))
                .toList();
        return new BatchView(batchId, status, version, publishedAt, memberViews, edgeViews);
    }

    /**
     * 结构化指纹：成员（申请+版本）与依赖边先按申请编号排序再序列化，
     * 集合顺序差异不产生异参误判；JSON 结构保证含分隔符文本也无歧义。
     */
    private String fingerprint(PublishBatchRequest req, List<BatchMemberInput> members,
                               List<BatchEdgeInput> edges) {
        List<List<Object>> memberParts = members.stream()
                .sorted(Comparator.comparing(BatchMemberInput::requestId))
                .map(m -> List.<Object>of(m.requestId(), m.expectedVersion()))
                .toList();
        List<List<String>> edgeParts = edges.stream()
                .map(e -> List.of(e.predecessor(), e.successor()))
                .sorted(Comparator.comparing((List<String> e) -> e.get(0))
                        .thenComparing(e -> e.get(1)))
                .toList();
        return FingerprintUtil.sha256("BATCH_PUBLISH", req.requestUid(), req.batchId(),
                req.publishedAt(), memberParts, edgeParts);
    }

    private String writeSnapshot(BatchView view) {
        try {
            return JSON.writeValueAsString(view);
        } catch (Exception e) {
            throw new IllegalStateException("批次快照序列化失败", e);
        }
    }

    private BatchView readSnapshot(CutoverBatchPO batch) {
        try {
            return JSON.readValue(batch.getResultSnapshot(), BatchView.class);
        } catch (Exception e) {
            throw new IllegalStateException("批次快照反序列化失败", e);
        }
    }
}

