package com.example.starter.cutover.service;

import com.example.starter.cutover.BatchStatus;
import com.example.starter.cutover.BusinessRuleException;
import com.example.starter.cutover.ConflictException;
import com.example.starter.cutover.NotFoundException;
import com.example.starter.cutover.RequestStatus;
import com.example.starter.cutover.dto.BatchEdgeInput;
import com.example.starter.cutover.dto.BatchEdgeView;
import com.example.starter.cutover.dto.BatchMemberInput;
import com.example.starter.cutover.dto.BatchMemberView;
import com.example.starter.cutover.dto.BatchPublishResult;
import com.example.starter.cutover.dto.BatchView;
import com.example.starter.cutover.dto.BlockDetailView;
import com.example.starter.cutover.dto.PublishBatchRequest;
import com.example.starter.cutover.model.CutoverBatchEdgePO;
import com.example.starter.cutover.model.CutoverBatchMemberPO;
import com.example.starter.cutover.model.CutoverBatchPO;
import com.example.starter.cutover.model.CutoverBlockDetailPO;
import com.example.starter.cutover.model.CutoverRequestPO;
import com.example.starter.cutover.repo.BatchRepository;
import com.example.starter.cutover.repo.CutoverRepository;
import com.example.starter.cutover.support.FingerprintUtil;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import java.time.LocalDateTime;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 跨设备割接依赖批次服务：冻结发布、拓扑查询、阻断明细查询。
 *
 * <p>关键口径：</p>
 * <ul>
 *   <li>成员必须唯一；依赖边两端都在批内；自环、环路、成员已开始（非 APPROVED）、
 *       版本不符或已绑定其他批次，整批拒绝（422），不落任何数据；</li>
 *   <li>发布原子冻结成员、依赖边与窗口快照，并把成员绑定批次（版本加 1）；</li>
 *   <li>requestUid 幂等：指纹覆盖成员+版本集合、依赖边集合与发布精确时刻，
 *       同键同参重放首次冻结快照，同键异参 409，失败不占键；</li>
 *   <li>拓扑查询成员与边均按申请编号稳定排序。</li>
 * </ul>
 */
@Service
public class BatchService {

    private static final ObjectMapper JSON = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

    private final CutoverRepository repo;
    private final BatchRepository batchRepo;

    public BatchService(CutoverRepository repo, BatchRepository batchRepo) {
        this.repo = repo;
        this.batchRepo = batchRepo;
    }

    // ---------------- 发布 ----------------

    @Transactional
    public BatchPublishResult publish(PublishBatchRequest req) {
        // 全局写锁：与单申请启动/回退传播串行化，并发只形成一致顺序。
        repo.lockGlobal();

        List<BatchMemberInput> members = req.members();
        List<BatchEdgeInput> edges = req.edges() == null ? List.of() : req.edges();
        String fp = fingerprint(req, members, edges);

        CutoverBatchPO existed = batchRepo.findBatchByRequestUid(req.requestUid());
        if (existed != null) {
            if (!existed.getFingerprint().equals(fp)) {
                throw new ConflictException("requestUid=" + req.requestUid()
                        + " 已存在但发布参数不一致（同键异参）");
            }
            return new BatchPublishResult(true,
                    "同键同参重放，返回首次冻结结果", readSnapshot(existed));
        }

        // ---- 结构校验（任一失败整批拒绝，不落数据）----
        Set<String> memberIds = new TreeSet<>();
        for (BatchMemberInput m : members) {
            if (!memberIds.add(m.requestId())) {
                throw new BusinessRuleException("批次成员必须唯一，重复成员: " + m.requestId());
            }
        }
        Set<List<String>> edgeKeys = new HashSet<>();
        List<BatchEdgeInput> distinctEdges = new ArrayList<>();
        for (BatchEdgeInput e : edges) {
            if (e.predecessor().equals(e.successor())) {
                throw new BusinessRuleException("依赖边不允许自环: " + e.predecessor());
            }
            if (!memberIds.contains(e.predecessor()) || !memberIds.contains(e.successor())) {
                throw new BusinessRuleException("依赖边两端必须都在批内: "
                        + e.predecessor() + " -> " + e.successor());
            }
            if (edgeKeys.add(List.of(e.predecessor(), e.successor()))) {
                distinctEdges.add(e);
            }
        }
        assertAcyclic(memberIds, distinctEdges);

        // ---- 成员状态与版本校验（按申请编号排序逐个锁定，整批原子）----
        Map<String, CutoverRequestPO> locked = new LinkedHashMap<>();
        for (BatchMemberInput m : members.stream()
                .sorted(Comparator.comparing(BatchMemberInput::requestId)).toList()) {
            CutoverRequestPO po = repo.lockRequest(m.requestId());
            if (po == null) {
                throw new NotFoundException("批次成员割接申请不存在: " + m.requestId());
            }
            if (!RequestStatus.APPROVED.name().equals(po.getStatus())) {
                throw new BusinessRuleException("成员 " + m.requestId()
                        + " 不是已批准未开始状态（当前 " + po.getStatus() + "），整批拒绝");
            }
            if (po.getBatchId() != null) {
                throw new BusinessRuleException("成员 " + m.requestId()
                        + " 已绑定未结束批次 " + po.getBatchId() + "，整批拒绝");
            }
            if (!m.expectedVersion().equals(po.getVersion())) {
                throw new BusinessRuleException("成员 " + m.requestId()
                        + " 版本不符：expectedVersion=" + m.expectedVersion()
                        + "，当前版本=" + po.getVersion() + "，整批拒绝");
            }
            locked.put(m.requestId(), po);
        }

        // ---- 原子冻结：批次 + 成员窗口快照 + 依赖边 + 成员绑定 ----
        LocalDateTime now = LocalDateTime.now();
        CutoverBatchPO batch = new CutoverBatchPO();
        batch.setBatchId(req.batchId());
        batch.setRequestUid(req.requestUid());
        batch.setFingerprint(fp);
        batch.setStatus(BatchStatus.FROZEN.name());
        batch.setVersion(1L);
        batch.setPublishedAt(req.publishedAt());
        batch.setCreatedAt(now);
        batch.setUpdatedAt(now);

        List<CutoverBatchMemberPO> memberPos = new ArrayList<>();
        for (CutoverRequestPO po : locked.values()) {
            CutoverBatchMemberPO member = new CutoverBatchMemberPO();
            member.setBatchId(req.batchId());
            member.setRequestId(po.getRequestId());
            member.setWindowStart(po.getWindowStart());
            member.setWindowEnd(po.getWindowEnd());
            member.setCreatedAt(now);
            memberPos.add(member);
        }
        List<CutoverBatchEdgePO> edgePos = distinctEdges.stream()
                .sorted(Comparator.comparing(BatchEdgeInput::predecessor)
                        .thenComparing(BatchEdgeInput::successor))
                .map(e -> {
                    CutoverBatchEdgePO po = new CutoverBatchEdgePO();
                    po.setBatchId(req.batchId());
                    po.setPredecessor(e.predecessor());
                    po.setSuccessor(e.successor());
                    po.setCreatedAt(now);
                    return po;
                }).toList();

        BatchView view = buildView(req.batchId(), BatchStatus.FROZEN.name(), 1L,
                req.publishedAt(), memberPos, edgePos,
                locked.values().stream().map(CutoverRequestPO::getStatus).toList(),
                Map.of());
        batch.setResultSnapshot(writeSnapshot(view));

        batchRepo.insertBatch(batch);
        for (CutoverBatchMemberPO member : memberPos) {
            batchRepo.insertMember(member);
        }
        for (CutoverBatchEdgePO edge : edgePos) {
            batchRepo.insertEdge(edge);
        }
        for (String requestId : locked.keySet()) {
            repo.bindBatch(requestId, req.batchId(), now);
        }
        return new BatchPublishResult(false,
                "批次已发布并冻结，成员 " + memberPos.size() + " 个，依赖边 "
                        + edgePos.size() + " 条", view);
    }

    // ---------------- 查询 ----------------

    @Transactional(readOnly = true)
    public BatchView getBatch(String batchId) {
        CutoverBatchPO batch = batchRepo.findBatch(batchId);
        if (batch == null) {
            throw new NotFoundException("依赖批次不存在: " + batchId);
        }
        List<CutoverBatchMemberPO> members = batchRepo.listMembers(batchId);
        List<CutoverBatchEdgePO> edges = batchRepo.listEdges(batchId);
        List<String> statuses = members.stream()
                .map(m -> {
                    CutoverRequestPO po = repo.findRequest(m.getRequestId());
                    return po == null ? null : po.getStatus();
                }).toList();
        Map<String, List<String>> sources = new HashMap<>();
        for (CutoverBatchMemberPO m : members) {
            sources.put(m.getRequestId(),
                    batchRepo.listBlockSources(batchId, m.getRequestId()));
        }
        return buildView(batchId, batch.getStatus(), batch.getVersion(),
                batch.getPublishedAt(), members, edges, statuses, sources);
    }

    @Transactional(readOnly = true)
    public List<BatchEdgeView> listEdges(String batchId) {
        mustExist(batchId);
        return batchRepo.listEdges(batchId).stream()
                .map(e -> new BatchEdgeView(e.getPredecessor(), e.getSuccessor()))
                .toList();
    }

    @Transactional(readOnly = true)
    public List<BlockDetailView> listBlockDetails(String batchId) {
        mustExist(batchId);
        List<CutoverBlockDetailPO> details = batchRepo.listBlockDetails(batchId);
        Map<String, List<String>> grouped = new LinkedHashMap<>();
        Map<String, LocalDateTime> blockedAt = new HashMap<>();
        for (CutoverBlockDetailPO d : details) {
            grouped.computeIfAbsent(d.getRequestId(), k -> new ArrayList<>())
                    .add(d.getSourceId());
            blockedAt.putIfAbsent(d.getRequestId(), d.getBlockedAt());
        }
        return grouped.entrySet().stream()
                .map(e -> new BlockDetailView(e.getKey(), e.getValue(),
                        blockedAt.get(e.getKey())))
                .toList();
    }

    // ---------------- 内部方法 ----------------

    private void mustExist(String batchId) {
        if (batchRepo.findBatch(batchId) == null) {
            throw new NotFoundException("依赖批次不存在: " + batchId);
        }
    }

    /** Kahn 拓扑判定：存在环路则整批拒绝。 */
    private void assertAcyclic(Set<String> memberIds, List<BatchEdgeInput> edges) {
        Map<String, Integer> indegree = new HashMap<>();
        Map<String, List<String>> adjacency = new HashMap<>();
        for (String id : memberIds) {
            indegree.put(id, 0);
        }
        for (BatchEdgeInput e : edges) {
            indegree.merge(e.successor(), 1, Integer::sum);
            adjacency.computeIfAbsent(e.predecessor(), k -> new ArrayList<>())
                    .add(e.successor());
        }
        Deque<String> queue = new ArrayDeque<>();
        for (Map.Entry<String, Integer> en : indegree.entrySet()) {
            if (en.getValue() == 0) {
                queue.add(en.getKey());
            }
        }
        int visited = 0;
        while (!queue.isEmpty()) {
            String node = queue.poll();
            visited++;
            for (String next : adjacency.getOrDefault(node, List.of())) {
                if (indegree.merge(next, -1, Integer::sum) == 0) {
                    queue.add(next);
                }
            }
        }
        if (visited != memberIds.size()) {
            throw new BusinessRuleException("依赖边存在环路，整批拒绝");
        }
    }

    private BatchView buildView(String batchId, String status, Long version,
                                LocalDateTime publishedAt,
                                List<CutoverBatchMemberPO> members,
                                List<CutoverBatchEdgePO> edges,
                                List<String> memberStatuses,
                                Map<String, List<String>> blockSources) {
        List<BatchMemberView> memberViews = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) {
            CutoverBatchMemberPO m = members.get(i);
            memberViews.add(new BatchMemberView(m.getRequestId(),
                    i < memberStatuses.size() ? memberStatuses.get(i) : null,
                    m.getWindowStart(), m.getWindowEnd(),
                    blockSources.getOrDefault(m.getRequestId(), List.of())));
        }
        List<BatchEdgeView> edgeViews = edges.stream()
                .map(e -> new BatchEdgeView(e.getPredecessor(), e.getSuccessor()))
                .toList();
        return new BatchView(batchId, status, version, publishedAt, memberViews, edgeViews);
    }

    /**
     * 结构化指纹：成员（申请+版本）与依赖边先按申请编号排序再序列化，
     * 集合顺序差异不产生异参误判；JSON 结构保证含分隔符文本也无歧义。
     */
    private String fingerprint(PublishBatchRequest req, List<BatchMemberInput> members,
                               List<BatchEdgeInput> edges) {
        List<List<Object>> memberParts = members.stream()
                .sorted(Comparator.comparing(BatchMemberInput::requestId))
                .map(m -> List.<Object>of(m.requestId(), m.expectedVersion()))
                .toList();
        List<List<String>> edgeParts = edges.stream()
                .map(e -> List.of(e.predecessor(), e.successor()))
                .sorted(Comparator.comparing((List<String> e) -> e.get(0))
                        .thenComparing(e -> e.get(1)))
                .toList();
        return FingerprintUtil.sha256("BATCH_PUBLISH", req.requestUid(), req.batchId(),
                req.publishedAt(), memberParts, edgeParts);
    }

    private String writeSnapshot(BatchView view) {
        try {
            return JSON.writeValueAsString(view);
        } catch (Exception e) {
            throw new IllegalStateException("批次快照序列化失败", e);
        }
    }

    private BatchView readSnapshot(CutoverBatchPO batch) {
        try {
            return JSON.readValue(batch.getResultSnapshot(), BatchView.class);
        } catch (Exception e) {
            throw new IllegalStateException("批次快照反序列化失败", e);
        }
    }
}

