package com.example.starter.cutover.service;

import com.example.starter.cutover.BadRequestException;
import com.example.starter.cutover.BatchStatus;
import com.example.starter.cutover.BusinessRuleException;
import com.example.starter.cutover.EventType;
import com.example.starter.cutover.RequestStatus;
import com.example.starter.cutover.model.CutoverBatchEdgePO;
import com.example.starter.cutover.model.CutoverBatchMemberPO;
import com.example.starter.cutover.model.CutoverBlockDetailPO;
import com.example.starter.cutover.model.CutoverEventPO;
import com.example.starter.cutover.model.CutoverRequestPO;
import com.example.starter.cutover.repo.BatchRepository;
import com.example.starter.cutover.repo.CutoverRepository;
import com.example.starter.cutover.support.FingerprintUtil;
import java.time.LocalDateTime;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.springframework.stereotype.Service;

/**
 * 批次执行门禁与依赖阻断传播。
 *
 * <p>关键口径：</p>
 * <ul>
 *   <li>批内成员启动前，所有直接前置必须已验证通过并封板（SEALED）；
 *       前置仍在执行/待执行返回等待（不写步骤、不占幂等键）；
 *       前置已回退/超期/被阻断则 422；</li>
 *   <li>前置进入回退或超期时，在同一事务内把尚未开始（APPROVED）的全部可达后继
 *       转 DEPENDENCY_BLOCKED 并记录首个阻断来源集合；已开始成员不动，按原回退流程；</li>
 *   <li>全部成员到达终态时同事务收口批次为 FINISHED；</li>
 *   <li>调用方必须已持有全局写锁与相关申请行锁（见 CutoverService）。</li>
 * </ul>
 */
@Service
public class BatchGateService {

    /** 成员终态集合：批次收口判定使用。 */
    private static final Set<String> TERMINAL = Set.of(
            RequestStatus.SEALED.name(),
            RequestStatus.REJECTED.name(),
            RequestStatus.ROLLED_BACK.name(),
            RequestStatus.WINDOW_EXPIRED.name(),
            RequestStatus.DEPENDENCY_BLOCKED.name());

    /** 前置失败类状态：门禁直接 422，且作为阻断传播根因。 */
    private static final Set<String> FAILED = Set.of(
            RequestStatus.ROLLED_BACK.name(),
            RequestStatus.WINDOW_EXPIRED.name(),
            RequestStatus.DEPENDENCY_BLOCKED.name());

    private final CutoverRepository repo;
    private final BatchRepository batchRepo;

    public BatchGateService(CutoverRepository repo, BatchRepository batchRepo) {
        this.repo = repo;
        this.batchRepo = batchRepo;
    }

    /** 门禁结果：waiting=true 表示前置未封板，本次启动不放行。 */
    public record GateOutcome(boolean waiting, String message) {
        static GateOutcome proceed() {
            return new GateOutcome(false, "");
        }

        static GateOutcome waiting(String message) {
            return new GateOutcome(true, message);
        }
    }

    /**
     * 批内成员启动门禁。调用方已持有全局写锁与该申请行锁，且申请为 APPROVED。
     *
     * @return 放行或等待结果；版本/前置失败直接抛异常
     */
    public GateOutcome checkGate(CutoverRequestPO po, Long expectedVersion) {
        if (expectedVersion == null) {
            throw new BadRequestException(
                    "批次成员启动必须携带 expectedVersion（当前版本 " + po.getVersion() + "）");
        }
        if (!expectedVersion.equals(po.getVersion())) {
            throw new BusinessRuleException("expectedVersion=" + expectedVersion
                    + " 与当前版本 " + po.getVersion() + " 不符");
        }
        List<String> preds = predecessorsOf(po.getBatchId(), po.getRequestId());
        List<String> waitingOn = new ArrayList<>();
        for (String predId : preds) {
            CutoverRequestPO pred = repo.findRequest(predId);
            if (pred == null) {
                continue;
            }
            String st = pred.getStatus();
            if (RequestStatus.SEALED.name().equals(st)) {
                continue;
            }
            if (FAILED.contains(st)) {
                throw new BusinessRuleException("直接前置 " + predId + " 已处于 "
                        + st + "，依赖未满足，不能启动");
            }
            waitingOn.add(predId + "(" + st + ")");
        }
        if (!waitingOn.isEmpty()) {
            return GateOutcome.waiting("直接前置尚未验证封板，等待中: " + String.join(", ", waitingOn));
        }
        return GateOutcome.proceed();
    }

    /**
     * 依赖阻断传播：从回退/超期的申请出发，把批内尚未开始的全部可达后继
     * 在同一事务内转 DEPENDENCY_BLOCKED，并记录首个阻断来源集合（已阻断的不更新）。
     * 传播完成后做批次收口判定。
     */
    public void propagateDependencyBlock(String batchId, String failedRequestId,
                                         LocalDateTime at) {
        List<CutoverBatchEdgePO> edges = batchRepo.listEdges(batchId);
        Map<String, List<String>> adjacency = new HashMap<>();
        Map<String, List<String>> predMap = new HashMap<>();
        for (CutoverBatchEdgePO e : edges) {
            adjacency.computeIfAbsent(e.getPredecessor(), k -> new ArrayList<>())
                    .add(e.getSuccessor());
            predMap.computeIfAbsent(e.getSuccessor(), k -> new ArrayList<>())
                    .add(e.getPredecessor());
        }

        // 各节点根因来源集合：失败根为自身；被阻断节点为其失败/阻断前置来源的并集。
        Map<String, Set<String>> sources = new HashMap<>();
        sources.put(failedRequestId, Set.of(failedRequestId));

        LocalDateTime now = LocalDateTime.now();
        Deque<String> queue = new ArrayDeque<>();
        queue.add(failedRequestId);
        Set<String> visited = new LinkedHashSet<>();
        while (!queue.isEmpty()) {
            String node = queue.poll();
            if (!visited.add(node)) {
                continue;
            }
            for (String succ : adjacency.getOrDefault(node, List.of())) {
                CutoverRequestPO succPo = repo.lockRequest(succ);
                if (succPo == null) {
                    continue;
                }
                String st = succPo.getStatus();
                if (RequestStatus.APPROVED.name().equals(st)) {
                    // 尚未开始：转依赖阻断，记录首个阻断来源集合。
                    Set<String> succSources = collectSources(succ, predMap, sources, batchId);
                    repo.markDependencyBlocked(succ, now);
                    for (String src : succSources) {
                        CutoverBlockDetailPO detail = new CutoverBlockDetailPO();
                        detail.setBatchId(batchId);
                        detail.setRequestId(succ);
                        detail.setSourceId(src);
                        detail.setBlockedAt(at);
                        detail.setCreatedAt(now);
                        batchRepo.insertBlockDetail(detail);
                    }
                    sources.put(succ, succSources);
                    insertBlockEvent(batchId, succ, succSources, now);
                    queue.add(succ);
                } else if (RequestStatus.DEPENDENCY_BLOCKED.name().equals(st)) {
                    // 已阻断：保留首个阻断来源集合，仅继续向下游传播。
                    sources.putIfAbsent(succ, Set.copyOf(
                            batchRepo.listBlockSources(batchId, succ)));
                    queue.add(succ);
                }
                // 已开始（EXECUTING/VERIFIED/SEALED）或已回退成员：不动，不向下游传播，
                // 按各自原流程处理。
            }
        }
        maybeFinishBatch(batchId);
    }

    /** 全部成员到达终态时，把批次同事务收口为 FINISHED。 */
    public void maybeFinishBatch(String batchId) {
        List<CutoverBatchMemberPO> members = batchRepo.listMembers(batchId);
        if (members.isEmpty()) {
            return;
        }
        for (CutoverBatchMemberPO m : members) {
            CutoverRequestPO po = repo.findRequest(m.getRequestId());
            if (po == null || !TERMINAL.contains(po.getStatus())) {
                return;
            }
        }
        batchRepo.updateBatchStatus(batchId, BatchStatus.FINISHED.name(),
                LocalDateTime.now());
    }

    /** 直接前置集合（按申请编号稳定排序）。 */
    private List<String> predecessorsOf(String batchId, String requestId) {
        List<String> preds = new ArrayList<>();
        for (CutoverBatchEdgePO e : batchRepo.listEdges(batchId)) {
            if (e.getSuccessor().equals(requestId)) {
                preds.add(e.getPredecessor());
            }
        }
        preds.sort(String::compareTo);
        return preds;
    }

    /** 汇总被阻断节点的首个阻断来源：失败根本身 + 各失败/阻断前置的来源并集。 */
    private Set<String> collectSources(String succ, Map<String, List<String>> predMap,
                                       Map<String, Set<String>> sources, String batchId) {
        Set<String> result = new TreeSet<>();
        for (String pred : predMap.getOrDefault(succ, List.of())) {
            Set<String> known = sources.get(pred);
            if (known != null) {
                result.addAll(known);
                continue;
            }
            CutoverRequestPO predPo = repo.findRequest(pred);
            if (predPo == null) {
                continue;
            }
            String st = predPo.getStatus();
            if (RequestStatus.ROLLED_BACK.name().equals(st)
                    || RequestStatus.WINDOW_EXPIRED.name().equals(st)) {
                result.add(pred);
            } else if (RequestStatus.DEPENDENCY_BLOCKED.name().equals(st)) {
                result.addAll(batchRepo.listBlockSources(batchId, pred));
            }
        }
        return result;
    }

    /** 阻断审计事件（幂等键唯一，一个申请只阻断一次）。 */
    private void insertBlockEvent(String batchId, String requestId, Set<String> sources,
                                  LocalDateTime now) {
        CutoverEventPO event = new CutoverEventPO();
        event.setRequestUid("SYS-BLOCK-" + batchId + "-" + requestId);
        event.setRequestId(requestId);
        event.setEventType(EventType.DEPENDENCY_BLOCK.name());
        event.setSeqNo(null);
        event.setPayloadFingerprint(FingerprintUtil.sha256(
                "DEPENDENCY_BLOCK", batchId, requestId, List.copyOf(sources)));
        event.setResultSnapshot("{\"message\":\"前置回退/超期，依赖阻断，来源: "
                + String.join(",", sources) + "\"}");
        event.setLateFlag(false);
        event.setCreatedAt(now);
        repo.insertEvent(event);
    }
}

