package com.example.starter.cutover.web;

import com.example.starter.cutover.dto.BatchEdgeView;
import com.example.starter.cutover.dto.BatchPublishResult;
import com.example.starter.cutover.dto.BatchView;
import com.example.starter.cutover.dto.BlockDetailView;
import com.example.starter.cutover.dto.PublishBatchRequest;
import com.example.starter.cutover.service.BatchService;
import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 跨设备割接依赖批次 REST 接口：冻结发布、拓扑查询、阻断明细。
 */
@RestController
@RequestMapping("/api/cutover-batches")
public class BatchController {

    private final BatchService batchService;

    public BatchController(BatchService batchService) {
        this.batchService = batchService;
    }

    /** 发布依赖批次（requestUid 幂等）；首次 201，同键同参重放 200，同键异参 409。 */
    @PostMapping
    public ResponseEntity<BatchPublishResult> publish(
            @Valid @RequestBody PublishBatchRequest req) {
        BatchPublishResult result = batchService.publish(req);
        return ResponseEntity.status(result.replayed() ? HttpStatus.OK : HttpStatus.CREATED)
                .body(result);
    }

    /** 批次拓扑查询：成员（含窗口快照、当前状态、阻断来源）与依赖边，按申请编号稳定排序。 */
    @GetMapping("/{batchId}")
    public BatchView get(@PathVariable String batchId) {
        return batchService.getBatch(batchId);
    }

    /** 批次依赖边查询（按前置、后继稳定排序）。 */
    @GetMapping("/{batchId}/edges")
    public List<BatchEdgeView> edges(@PathVariable String batchId) {
        return batchService.listEdges(batchId);
    }

    /** 批次阻断明细：被阻断申请及其首个阻断来源集合。 */
    @GetMapping("/{batchId}/blocks")
    public List<BlockDetailView> blocks(@PathVariable String batchId) {
        return batchService.listBlockDetails(batchId);
    }
}

