package com.example.starter.cutover;

import static com.example.starter.cutover.CutoverFixtures.steps;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.starter.cutover.dto.ActionResult;
import com.example.starter.cutover.dto.ApproveRequest;
import com.example.starter.cutover.dto.BatchEdgeInput;
import com.example.starter.cutover.dto.BatchMemberInput;
import com.example.starter.cutover.dto.BatchPublishResult;
import com.example.starter.cutover.dto.BatchView;
import com.example.starter.cutover.dto.BlockDetailView;
import com.example.starter.cutover.dto.CreateCutoverRequest;
import com.example.starter.cutover.dto.ExpireCheckRequest;
import com.example.starter.cutover.dto.PublishBatchRequest;
import com.example.starter.cutover.dto.SealRequest;
import com.example.starter.cutover.dto.StartExecutionRequest;
import com.example.starter.cutover.dto.StepReportRequest;
import com.example.starter.cutover.service.BatchService;
import com.example.starter.cutover.service.CutoverService;
import java.time.LocalDateTime;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 跨设备依赖批次：发布、门禁、阻断传播主流程与失败分支（真实 H2，无 mock）。
 */
@SpringBootTest
class BatchServiceTest {

    private static final LocalDateTime BASE = LocalDateTime.of(2027, 1, 5, 2, 0);
    private static final LocalDateTime END = BASE.plusHours(2);
    private static final LocalDateTime PUBLISHED_AT = BASE.minusHours(3);

    private static final String DEV1 = "DEV-CORE-SW-01";
    private static final String DEV2 = "DEV-CORE-SW-02";
    private static final String DEV3 = "DEV-DB-01";
    private static final String DEV4 = "DEV-FW-01";

    @Autowired
    private CutoverService service;
    @Autowired
    private BatchService batchService;
    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM cutover_block_detail");
        jdbc.update("DELETE FROM cutover_batch_edge");
        jdbc.update("DELETE FROM cutover_batch_member");
        jdbc.update("DELETE FROM cutover_batch");
        jdbc.update("DELETE FROM cutover_event");
        jdbc.update("DELETE FROM cutover_step");
        jdbc.update("DELETE FROM cutover_request");
    }

    // ---------------- 工具 ----------------

    private void prepareApproved(String id, String device) {
        service.create(new CreateCutoverRequest(id, "割接-" + id, device,
                Priority.MEDIUM, BASE, END,
                steps("停流量", "NORMAL", "硬检查", "HARDCHECK")));
        service.analyze(id);
        service.approve(new ApproveRequest("ap-" + id, id, true, null));
    }

    private long versionOf(String id) {
        return service.get(id).version();
    }

    private PublishBatchRequest publishReq(String uid, String batchId, List<String> memberIds,
                                           List<BatchEdgeInput> edges) {
        List<BatchMemberInput> members = memberIds.stream()
                .map(id -> new BatchMemberInput(id, versionOf(id))).toList();
        return new PublishBatchRequest(uid, batchId, members, edges, PUBLISHED_AT);
    }

    private BatchPublishResult publish(String uid, String batchId, List<String> memberIds,
                                       List<BatchEdgeInput> edges) {
        return batchService.publish(publishReq(uid, batchId, memberIds, edges));
    }

    /** 让申请执行并封板（批次成员自动带 expectedVersion 过门禁）。 */
    private void executeAndSeal(String id) {
        service.startExecution(new StartExecutionRequest("ex-" + id, id, BASE, versionOf(id)));
        service.report(new StepReportRequest("r1-" + id, id, 1, true,
                BASE.plusMinutes(10), null));
        service.report(new StepReportRequest("r2-" + id, id, 2, true,
                BASE.plusMinutes(20), null));
        service.seal(new SealRequest("seal-" + id, id));
    }

    // ---------------- 发布主流程 ----------------

    @Test
    @DisplayName("发布主流程：原子冻结成员/依赖/窗口快照并绑定批次，拓扑按申请编号稳定排序")
    void publishHappyFlow() {
        prepareApproved("R-C", DEV3);
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        // 乱序提交成员，验证稳定排序
        BatchPublishResult result = publish("pub-1", "B-1",
                List.of("R-C", "R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B"),
                        new BatchEdgeInput("R-A", "R-C")));

        assertThat(result.replayed()).isFalse();
        BatchView view = result.batch();
        assertThat(view.status()).isEqualTo("FROZEN");
        assertThat(view.version()).isEqualTo(1L);
        assertThat(view.publishedAt()).isEqualTo(PUBLISHED_AT);
        assertThat(view.members()).extracting(m -> m.requestId())
                .containsExactly("R-A", "R-B", "R-C");
        // 窗口快照冻结
        assertThat(view.members()).allSatisfy(m -> {
            assertThat(m.windowStart()).isEqualTo(BASE);
            assertThat(m.windowEnd()).isEqualTo(END);
            assertThat(m.status()).isEqualTo("APPROVED");
        });
        assertThat(view.edges()).extracting(e -> e.predecessor() + "->" + e.successor())
                .containsExactly("R-A->R-B", "R-A->R-C");

        // 成员绑定批次且版本加 1
        long bindVersion = versionOf("R-A");
        assertThat(service.get("R-A").batchId()).isEqualTo("B-1");
        assertThat(bindVersion).isEqualTo(4L); // create1 -> analyze2 -> approve3 -> bind4

        // 拓扑查询与依赖查询
        BatchView queried = batchService.getBatch("B-1");
        assertThat(queried.members()).extracting(m -> m.requestId())
                .containsExactly("R-A", "R-B", "R-C");
        assertThat(batchService.listEdges("B-1"))
                .extracting(e -> e.predecessor() + "->" + e.successor())
                .containsExactly("R-A->R-B", "R-A->R-C");
    }

    @Test
    @DisplayName("发布失败分支：重复成员/边出批/自环/环路/非批准/已开始/版本不符/已绑定 整批拒绝")
    void publishRejections() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        prepareApproved("R-C", DEV3);

        // 重复成员
        assertThatThrownBy(() -> publish("p-dup", "B-DUP", List.of("R-A", "R-A"), List.of()))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("唯一");
        // 边端点不在批内
        assertThatThrownBy(() -> publish("p-out", "B-OUT", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-X"))))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("批内");
        // 自环
        assertThatThrownBy(() -> publish("p-self", "B-SELF", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-A"))))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("自环");
        // 环路
        assertThatThrownBy(() -> publish("p-cyc", "B-CYC", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B"),
                        new BatchEdgeInput("R-B", "R-A"))))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("环路");
        // 成员不存在 -> 404
        assertThatThrownBy(() -> batchService.publish(new PublishBatchRequest("p-404", "B-404",
                List.of(new BatchMemberInput("R-A", versionOf("R-A")),
                        new BatchMemberInput("R-NONE", 1L)),
                List.of(), PUBLISHED_AT)))
                .isInstanceOf(NotFoundException.class);
        // 版本不符
        assertThatThrownBy(() -> batchService.publish(new PublishBatchRequest("p-ver", "B-VER",
                List.of(new BatchMemberInput("R-A", versionOf("R-A") + 1)),
                List.of(), PUBLISHED_AT)))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("版本不符");

        // 未批准成员（仅提交未审批）
        service.create(new CreateCutoverRequest("R-SUB", "割接-R-SUB", DEV4,
                Priority.MEDIUM, BASE, END, steps("停流量", "NORMAL")));
        assertThatThrownBy(() -> batchService.publish(new PublishBatchRequest("p-st", "B-ST",
                List.of(new BatchMemberInput("R-SUB", versionOf("R-SUB"))),
                List.of(), PUBLISHED_AT)))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("整批拒绝");

        // 已开始成员
        prepareApproved("R-EX", DEV4);
        // R-EX 与 R-SUB 同设备同窗口 -> R-SUB 已被抢占拒绝；换设备重备
        // 此处 R-EX 在 DEV4 已批准，直接启动
        service.startExecution(new StartExecutionRequest("ex-R-EX", "R-EX", BASE));
        assertThatThrownBy(() -> batchService.publish(new PublishBatchRequest("p-ex", "B-EX",
                List.of(new BatchMemberInput("R-EX", versionOf("R-EX"))),
                List.of(), PUBLISHED_AT)))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("整批拒绝");

        // 已绑定其他未结束批次
        publish("p-1", "B-1", List.of("R-A", "R-B"), List.of());
        assertThatThrownBy(() -> publish("p-2", "B-2", List.of("R-A"), List.of()))
                .isInstanceOf(BusinessRuleException.class).hasMessageContaining("已绑定");

        // 上述失败均不落批次数据
        Integer batchCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM cutover_batch", Integer.class);
        assertThat(batchCount).isEqualTo(1);
    }

    @Test
    @DisplayName("发布失败不占键：同 requestUid 修正参数后可成功发布")
    void publishFailureDoesNotConsumeKey() {
        prepareApproved("R-A", DEV1);
        PublishBatchRequest bad = new PublishBatchRequest("p-retry", "B-R",
                List.of(new BatchMemberInput("R-A", 99L)), List.of(), PUBLISHED_AT);
        assertThatThrownBy(() -> batchService.publish(bad))
                .isInstanceOf(BusinessRuleException.class);

        PublishBatchRequest good = new PublishBatchRequest("p-retry", "B-R",
                List.of(new BatchMemberInput("R-A", versionOf("R-A"))), List.of(), PUBLISHED_AT);
        BatchPublishResult result = batchService.publish(good);
        assertThat(result.replayed()).isFalse();
        assertThat(result.batch().status()).isEqualTo("FROZEN");
    }

    @Test
    @DisplayName("发布幂等：同键同参重放首次冻结快照（成员乱序同参）；同键异参 409")
    void publishIdempotentReplayAndConflict() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        BatchPublishResult first = publish("p-idem", "B-IDEM", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B")));
        assertThat(first.replayed()).isFalse();

        // 成员顺序不同但集合相同 -> 同参重放
        PublishBatchRequest reordered = new PublishBatchRequest("p-idem", "B-IDEM",
                List.of(new BatchMemberInput("R-B", versionOf("R-B") - 1 + 1),
                        new BatchMemberInput("R-A", 3L)),
                List.of(new BatchEdgeInput("R-A", "R-B")), PUBLISHED_AT);
        // 注意：版本快照以首次发布为准，此处用发布时版本 3 重放
        BatchPublishResult replay = batchService.publish(reordered);
        assertThat(replay.replayed()).isTrue();
        assertThat(replay.batch()).isEqualTo(first.batch());

        // 首次快照被冻结：成员启动后重放仍返回发布时状态
        service.startExecution(new StartExecutionRequest("ex-R-A", "R-A", BASE,
                versionOf("R-A")));
        BatchPublishResult replayAfterStart = batchService.publish(
                publishReq("p-idem", "B-IDEM", List.of("R-A", "R-B"),
                        List.of(new BatchEdgeInput("R-A", "R-B"))));
        assertThat(replayAfterStart.replayed()).isTrue();
        assertThat(replayAfterStart.batch().members())
                .allSatisfy(m -> assertThat(m.status()).isEqualTo("APPROVED"));

        // 同键异参（发布时刻不同）-> 409
        PublishBatchRequest conflict = new PublishBatchRequest("p-idem", "B-IDEM",
                List.of(new BatchMemberInput("R-A", 3L), new BatchMemberInput("R-B", 3L)),
                List.of(new BatchEdgeInput("R-A", "R-B")), PUBLISHED_AT.plusMinutes(1));
        assertThatThrownBy(() -> batchService.publish(conflict))
                .isInstanceOf(ConflictException.class);
    }

    @Test
    @DisplayName("指纹结构化无歧义：申请号含分隔符时，不同成员集合不会被误判为同参")
    void fingerprintUnambiguousWithDelimiters() {
        // 朴素拼接下 "A,B"+"C" 与 "A"+"B,C" 会碰撞，结构化指纹必须区分
        prepareApproved("R-A,B", DEV1);
        prepareApproved("R-C", DEV2);
        prepareApproved("R-A", DEV3);
        prepareApproved("R-B,C", DEV4);

        BatchPublishResult first = batchService.publish(new PublishBatchRequest("p-sep", "B-SEP",
                List.of(new BatchMemberInput("R-A,B", versionOf("R-A,B")),
                        new BatchMemberInput("R-C", versionOf("R-C"))),
                List.of(), PUBLISHED_AT));
        assertThat(first.replayed()).isFalse();

        // 同键但成员集合不同（朴素拼接指纹会相同）-> 必须 409
        PublishBatchRequest collision = new PublishBatchRequest("p-sep", "B-SEP",
                List.of(new BatchMemberInput("R-A", versionOf("R-A")),
                        new BatchMemberInput("R-B,C", versionOf("R-B,C"))),
                List.of(), PUBLISHED_AT);
        assertThatThrownBy(() -> batchService.publish(collision))
                .isInstanceOf(ConflictException.class);
    }

    // ---------------- 执行门禁 ----------------

    @Test
    @DisplayName("门禁：前置未封板返回等待（不写步骤不占键），前置封板后同键启动成功")
    void gateWaitingThenStartAfterPredecessorSealed() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        publish("p-g", "B-G", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B")));

        // 前置 R-A 未封板：R-B 启动返回等待
        ActionResult waiting = service.startExecution(
                new StartExecutionRequest("ex-R-B", "R-B", BASE, versionOf("R-B")));
        assertThat(waiting.waiting()).isTrue();
        assertThat(waiting.replayed()).isFalse();
        assertThat(waiting.request().status()).isEqualTo("APPROVED");
        // 不写步骤、不占幂等键
        assertThat(service.get("R-B").steps())
                .allSatisfy(s -> assertThat(s.status()).isEqualTo("PENDING"));
        assertThat(service.events("R-B")).isEmpty();

        // 前置执行并封板
        executeAndSeal("R-A");

        // 同 requestUid 重试：未占键，正常启动
        ActionResult started = service.startExecution(
                new StartExecutionRequest("ex-R-B", "R-B", BASE, versionOf("R-B")));
        assertThat(started.waiting()).isFalse();
        assertThat(started.request().status()).isEqualTo("EXECUTING");
        assertThat(service.events("R-B"))
                .extracting(e -> e.eventType()).contains("EXECUTE_START");
    }

    @Test
    @DisplayName("门禁：批次成员缺 expectedVersion 400，版本不符 422；未绑定批次旧申请不需要版本")
    void gateVersionChecks() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        publish("p-v", "B-V", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B")));

        // 缺 expectedVersion -> 400
        assertThatThrownBy(() -> service.startExecution(
                new StartExecutionRequest("ex-nv", "R-B", BASE)))
                .isInstanceOf(BadRequestException.class)
                .hasMessageContaining("expectedVersion");
        // 版本不符 -> 422
        assertThatThrownBy(() -> service.startExecution(
                new StartExecutionRequest("ex-wv", "R-B", BASE, versionOf("R-B") + 1)))
                .isInstanceOf(BusinessRuleException.class)
                .hasMessageContaining("不符");

        // 未绑定批次的旧单申请：不需要 expectedVersion，行为不变
        prepareApproved("R-OLD", DEV3);
        ActionResult old = service.startExecution(
                new StartExecutionRequest("ex-old", "R-OLD", BASE));
        assertThat(old.request().status()).isEqualTo("EXECUTING");
    }

    // ---------------- 阻断传播 ----------------

    @Test
    @DisplayName("前置回退同事务传播：可达后继转依赖阻断并记录首个来源，无关支路可继续")
    void rollbackPropagatesToReachableSuccessors() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        prepareApproved("R-C", DEV3);
        prepareApproved("R-D", DEV4);
        // A -> B -> C，D 无关支路
        publish("p-p", "B-P", List.of("R-A", "R-B", "R-C", "R-D"),
                List.of(new BatchEdgeInput("R-A", "R-B"),
                        new BatchEdgeInput("R-B", "R-C")));

        // A 执行后第一步失败 -> STEP_FAILED 回退
        service.startExecution(new StartExecutionRequest("ex-R-A", "R-A", BASE,
                versionOf("R-A")));
        service.report(new StepReportRequest("r1-R-A", "R-A", 1, false,
                BASE.plusMinutes(10), null));

        assertThat(service.get("R-A").status()).isEqualTo("ROLLED_BACK");
        // 同事务传播：B、C 均已阻断（级联），首个阻断来源都是 R-A
        assertThat(service.get("R-B").status()).isEqualTo("DEPENDENCY_BLOCKED");
        assertThat(service.get("R-C").status()).isEqualTo("DEPENDENCY_BLOCKED");
        List<BlockDetailView> details = batchService.listBlockDetails("B-P");
        assertThat(details).hasSize(2);
        assertThat(details).extracting(d -> d.requestId())
                .containsExactly("R-B", "R-C");
        assertThat(details).allSatisfy(d -> assertThat(d.sources())
                .containsExactly("R-A"));
        // 阻断审计事件
        assertThat(service.events("R-B"))
                .extracting(e -> e.eventType()).contains("DEPENDENCY_BLOCK");

        // 无关支路 D 不受影响，可正常启动并完成
        ActionResult dStart = service.startExecution(
                new StartExecutionRequest("ex-R-D", "R-D", BASE, versionOf("R-D")));
        assertThat(dStart.request().status()).isEqualTo("EXECUTING");

        // 被阻断成员是终态：启动 422
        assertThatThrownBy(() -> service.startExecution(
                new StartExecutionRequest("ex-R-B2", "R-B", BASE, versionOf("R-B"))))
                .isInstanceOf(BusinessRuleException.class);

        // 批次收口：A 回退、B/C 阻断、D 完成后 -> FINISHED
        executeAndSeal("R-D");
        assertThat(batchService.getBatch("B-P").status()).isEqualTo("FINISHED");
    }

    @Test
    @DisplayName("链中失败传播：已封板前置结果不改，未开始后继阻断，来源为失败根")
    void midChainFailureKeepsSealedAndBlocksDownstream() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        prepareApproved("R-C", DEV3);
        publish("p-m", "B-M", List.of("R-A", "R-B", "R-C"),
                List.of(new BatchEdgeInput("R-A", "R-B"),
                        new BatchEdgeInput("R-B", "R-C")));

        executeAndSeal("R-A");
        // B 启动后失败回退
        service.startExecution(new StartExecutionRequest("ex-R-B", "R-B", BASE,
                versionOf("R-B")));
        service.report(new StepReportRequest("r1-R-B", "R-B", 1, false,
                BASE.plusMinutes(10), null));

        assertThat(service.get("R-A").status()).isEqualTo("SEALED"); // 已封板不改
        assertThat(service.get("R-B").status()).isEqualTo("ROLLED_BACK");
        assertThat(service.get("R-C").status()).isEqualTo("DEPENDENCY_BLOCKED");
        assertThat(batchService.listBlockDetails("B-M"))
                .singleElement()
                .satisfies(d -> {
                    assertThat(d.requestId()).isEqualTo("R-C");
                    assertThat(d.sources()).containsExactly("R-B");
                });
        // 全部终态 -> 批次收口
        assertThat(batchService.getBatch("B-M").status()).isEqualTo("FINISHED");
    }

    @Test
    @DisplayName("前置窗口超期：同事务传播依赖阻断，阻断明细 blockedAt 为超期判定时刻")
    void windowExpiryPropagatesBlock() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        publish("p-e", "B-E", List.of("R-A", "R-B"),
                List.of(new BatchEdgeInput("R-A", "R-B")));

        service.startExecution(new StartExecutionRequest("ex-R-A", "R-A", BASE,
                versionOf("R-A")));
        // 窗口结束仍有未完成步骤 -> WINDOW_EXPIRED 并传播
        service.expireCheck(new ExpireCheckRequest("exp-R-A", "R-A", END));

        assertThat(service.get("R-A").status()).isEqualTo("WINDOW_EXPIRED");
        assertThat(service.get("R-B").status()).isEqualTo("DEPENDENCY_BLOCKED");
        assertThat(batchService.listBlockDetails("B-E"))
                .singleElement()
                .satisfies(d -> {
                    assertThat(d.sources()).containsExactly("R-A");
                    assertThat(d.blockedAt()).isEqualTo(END);
                });
    }

    @Test
    @DisplayName("阻断明细保留首个来源集合：多前置分别失败时，先阻断者来源不被覆盖")
    void blockDetailsKeepFirstSources() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        prepareApproved("R-C", DEV3);
        prepareApproved("R-D", DEV4);
        // A -> C，B -> C，C -> D
        publish("p-f", "B-F", List.of("R-A", "R-B", "R-C", "R-D"),
                List.of(new BatchEdgeInput("R-A", "R-C"),
                        new BatchEdgeInput("R-B", "R-C"),
                        new BatchEdgeInput("R-C", "R-D")));

        // A 先失败：C 被阻断（来源 {A}），D 级联阻断（来源 {A}）
        service.startExecution(new StartExecutionRequest("ex-R-A", "R-A", BASE,
                versionOf("R-A")));
        service.report(new StepReportRequest("r1-R-A", "R-A", 1, false,
                BASE.plusMinutes(10), null));
        assertThat(service.get("R-C").status()).isEqualTo("DEPENDENCY_BLOCKED");

        // B 后失败：C 已阻断，首个来源集合保留 {A}，不追加 B
        service.startExecution(new StartExecutionRequest("ex-R-B", "R-B", BASE,
                versionOf("R-B")));
        service.report(new StepReportRequest("r1-R-B", "R-B", 1, false,
                BASE.plusMinutes(10), null));

        List<BlockDetailView> details = batchService.listBlockDetails("B-F");
        assertThat(details).extracting(d -> d.requestId())
                .containsExactly("R-C", "R-D");
        assertThat(details).allSatisfy(d -> assertThat(d.sources())
                .containsExactly("R-A"));
        // 拓扑查询成员视图携带阻断来源
        BatchView view = batchService.getBatch("B-F");
        assertThat(view.members())
                .filteredOn(m -> m.requestId().equals("R-C"))
                .singleElement()
                .satisfies(m -> assertThat(m.blockingSources()).containsExactly("R-A"));
    }

    @Test
    @DisplayName("批次查询：未知批次 404；成员全部封板后批次 FINISHED")
    void batchQueriesAndFinishBySeal() {
        prepareApproved("R-A", DEV1);
        prepareApproved("R-B", DEV2);
        publish("p-q", "B-Q", List.of("R-A", "R-B"), List.of());

        assertThatThrownBy(() -> batchService.getBatch("B-NONE"))
                .isInstanceOf(NotFoundException.class);
        assertThatThrownBy(() -> batchService.listEdges("B-NONE"))
                .isInstanceOf(NotFoundException.class);
        assertThatThrownBy(() -> batchService.listBlockDetails("B-NONE"))
                .isInstanceOf(NotFoundException.class);

        executeAndSeal("R-A");
        assertThat(batchService.getBatch("B-Q").status()).isEqualTo("FROZEN");
        executeAndSeal("R-B");
        assertThat(batchService.getBatch("B-Q").status()).isEqualTo("FINISHED");
    }
}

