                    return e;
                }
            });
            start2.countDown();
            Object o1 = safeGet(g1);
            Object o2 = safeGet(g2);
            int conflicts = (o1 instanceof ConflictException ? 1 : 0)
                    + (o2 instanceof ConflictException ? 1 : 0);
            int successes = (o1 instanceof BatchPublishResult ? 1 : 0)
