package com.example.starter.cutover.web;

import static org.assertj.core.api.Assertions.assertThat;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 依赖批次 HTTP 端到端：发布/重放/409、拓扑与阻断明细查询、门禁等待与版本错误码。
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class BatchControllerIT {

    private static final LocalDateTime BASE = LocalDateTime.of(2027, 3, 1, 2, 0);
    private static final LocalDateTime END = BASE.plusHours(2);
    private static final LocalDateTime PUBLISHED_AT = BASE.minusHours(3);

    @Autowired
    private TestRestTemplate rest;
    @Autowired
    private ObjectMapper mapper;
    @Autowired
    private JdbcTemplate jdbc;

    private final HttpHeaders json = new HttpHeaders();

    @BeforeEach
    void setUp() {
        json.setContentType(MediaType.APPLICATION_JSON);
        jdbc.update("DELETE FROM cutover_block_detail");
        jdbc.update("DELETE FROM cutover_batch_edge");
        jdbc.update("DELETE FROM cutover_batch_member");
        jdbc.update("DELETE FROM cutover_batch");
        jdbc.update("DELETE FROM cutover_event");
        jdbc.update("DELETE FROM cutover_step");
        jdbc.update("DELETE FROM cutover_request");
    }

    private ResponseEntity<String> post(String path, Object body) {
        return rest.postForEntity(path, new HttpEntity<>(body, json), String.class);
    }

    private Map<String, Object> cutoverBody(String id, String device) {
        return Map.of(
                "requestId", id,
                "title", "夜间割接-" + id,
                "deviceCode", device,
                "priority", "MEDIUM",
                "windowStart", BASE.toString(),
                "windowEnd", END.toString(),
                "steps", List.of(
                        Map.of("name", "停流量", "type", "NORMAL"),
                        Map.of("name", "硬检查", "type", "HARDCHECK")));
    }

    private long prepareApproved(String id, String device) throws Exception {
        assertThat(post("/api/cutovers", cutoverBody(id, device)).getStatusCode())
                .isEqualTo(HttpStatus.CREATED);
        post("/api/cutovers/" + id + "/impact-analysis", null);
        post("/api/cutovers/approve",
                Map.of("requestUid", "ap-" + id, "requestId", id, "approved", true));
        String body = rest.getForEntity("/api/cutovers/" + id, String.class).getBody();
        return mapper.readTree(body).path("version").asLong();
    }

    private Map<String, Object> publishBody(String uid, String batchId,
                                            List<Map<String, Object>> members,
                                            List<Map<String, String>> edges) {
        return Map.of(
                "requestUid", uid,
                "batchId", batchId,
                "members", members,
                "edges", edges,
                "publishedAt", PUBLISHED_AT.toString());
    }

    @Test
    @DisplayName("HTTP 批次端到端：发布 201/重放 200/异参 409，门禁等待->封板->启动，阻断明细可查")
    void batchHttpEndToEnd() throws Exception {
        long va = prepareApproved("H-A", "DEV-CORE-SW-01");
        long vb = prepareApproved("H-B", "DEV-CORE-SW-02");

        Map<String, Object> body = publishBody("pub-h", "B-H",
                List.of(Map.of("requestId", "H-A", "expectedVersion", va),
                        Map.of("requestId", "H-B", "expectedVersion", vb)),
                List.of(Map.of("predecessor", "H-A", "successor", "H-B")));

        // 发布 201
        ResponseEntity<String> published = post("/api/cutover-batches", body);
        assertThat(published.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        JsonNode batch = mapper.readTree(published.getBody()).path("batch");
        assertThat(batch.path("status").asText()).isEqualTo("FROZEN");
        assertThat(batch.path("version").asLong()).isEqualTo(1L);
        assertThat(batch.path("members")).hasSize(2);

        // 同键同参重放 200 + replayed
        ResponseEntity<String> replay = post("/api/cutover-batches", body);
        assertThat(replay.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(mapper.readTree(replay.getBody()).path("replayed").asBoolean()).isTrue();

        // 同键异参 409
        Map<String, Object> conflict = publishBody("pub-h", "B-H",
                List.of(Map.of("requestId", "H-A", "expectedVersion", va)),
                List.of());
        assertThat(post("/api/cutover-batches", conflict).getStatusCode())
                .isEqualTo(HttpStatus.CONFLICT);

        // 拓扑查询：成员按申请编号排序
        ResponseEntity<String> topo = rest.getForEntity("/api/cutover-batches/B-H", String.class);
        assertThat(topo.getStatusCode()).isEqualTo(HttpStatus.OK);
        JsonNode members = mapper.readTree(topo.getBody()).path("members");
        assertThat(members.get(0).path("requestId").asText()).isEqualTo("H-A");
        assertThat(members.get(1).path("requestId").asText()).isEqualTo("H-B");

        // 依赖查询
        ResponseEntity<String> edges = rest.getForEntity(
                "/api/cutover-batches/B-H/edges", String.class);
        assertThat(edges.getBody()).contains("H-A").contains("H-B");

        // 未知批次 404
        assertThat(rest.getForEntity("/api/cutover-batches/B-NONE", String.class)
                .getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);

        // 批次成员缺 expectedVersion -> 400
        assertThat(post("/api/cutovers/execute", Map.of(
                "requestUid", "ex-hb-0", "requestId", "H-B", "startTime", BASE.toString()))
                .getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        // 版本不符 -> 422
        assertThat(post("/api/cutovers/execute", Map.of(
                "requestUid", "ex-hb-1", "requestId", "H-B",
                "startTime", BASE.toString(), "expectedVersion", 99))
                .getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);

        // 前置未封板 -> 200 + waiting=true，不写步骤
        long vbNow = mapper.readTree(rest.getForEntity("/api/cutovers/H-B", String.class)
                .getBody()).path("version").asLong();
        ResponseEntity<String> waiting = post("/api/cutovers/execute", Map.of(
                "requestUid", "ex-hb", "requestId", "H-B",
                "startTime", BASE.toString(), "expectedVersion", vbNow));
        assertThat(waiting.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(mapper.readTree(waiting.getBody()).path("waiting").asBoolean()).isTrue();

        // 前置执行并封板
        long vaNow = mapper.readTree(rest.getForEntity("/api/cutovers/H-A", String.class)
                .getBody()).path("version").asLong();
        post("/api/cutovers/execute", Map.of(
                "requestUid", "ex-ha", "requestId", "H-A",
                "startTime", BASE.toString(), "expectedVersion", vaNow));
        post("/api/cutovers/steps/report", Map.of(
                "requestUid", "r1-ha", "requestId", "H-A", "seqNo", 1,
                "success", true, "reportedAt", BASE.plusMinutes(10).toString()));
        // 第二步硬性检查失败 -> 回退并同事务阻断 H-B
        post("/api/cutovers/steps/report", Map.of(
                "requestUid", "r2-ha", "requestId", "H-A", "seqNo", 2,
                "success", false, "reportedAt", BASE.plusMinutes(20).toString()));

        // 阻断明细查询
        ResponseEntity<String> blocks = rest.getForEntity(
                "/api/cutover-batches/B-H/blocks", String.class);
        assertThat(blocks.getStatusCode()).isEqualTo(HttpStatus.OK);
        JsonNode blockNode = mapper.readTree(blocks.getBody());
        assertThat(blockNode).hasSize(1);
        assertThat(blockNode.get(0).path("requestId").asText()).isEqualTo("H-B");
        assertThat(blockNode.get(0).path("sources").get(0).asText()).isEqualTo("H-A");

        // 被阻断成员启动 -> 422
        assertThat(post("/api/cutovers/execute", Map.of(
                "requestUid", "ex-hb-2", "requestId", "H-B",
                "startTime", BASE.toString(), "expectedVersion", vbNow))
                .getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
    }

    @Test
    @DisplayName("HTTP 校验：发布参数非法 400（缺成员/缺时刻/空批次号）")
    void publishValidation400() {
        assertThat(post("/api/cutover-batches", Map.of(
                "requestUid", "v-1", "batchId", "B-V",
                "members", List.of(),
                "publishedAt", PUBLISHED_AT.toString()))
                .getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(post("/api/cutover-batches", Map.of(
                "requestUid", "v-2", "batchId", "B-V",
                "members", List.of(Map.of("requestId", "X", "expectedVersion", 1))))
                .getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
    }
}

